        assertTrue(ScheduleEvaluator.shouldBeActiveAt(LocalDateTime.of(2026, 8, 11, 7, 59), listOf(defaultWindow)))
        assertFalse(ScheduleEvaluator.shouldBeActiveAt(LocalDateTime.of(2026, 8, 11, 8, 0), listOf(defaultWindow)))
    }

