        // 3 breaks used, budget 0, interval elapsed — still blocked by budget.
        assertFalse(BreakPolicy.isBreakAllowed(at(2026, 8, 10, 23, 30), listOf(defaultWindow), breaks, instant(2026, 8, 10, 23, 0)))
    }

