        // Tuesday evening, 21:00 — a NEW window (Tuesday's 20:00). Budget is fresh.
        assertEquals(3, BreakPolicy.budgetRemaining(at(2026, 8, 11, 21, 0), listOf(defaultWindow), mondayBreaks))
    }

